import numpy as np

_TARGET_SEQ = (2, 3, 1, 3, 1, 2, 4, 2)
_TOTAL_PROGRESS = len(_TARGET_SEQ)
_INIT_POS = (8, 14)
_SIZE = 5
_STEP = 6


def engine(grid, action, data):
    g = grid.copy()
    H, W = g.shape

    score = 0
    for col in range(W - 1, -1, -1):
        if g[H - 1, col] == 1:
            score += 1
        else:
            break

    pos = None
    if H >= _SIZE and W >= _SIZE:
        for r in range(H - _SIZE + 1):
            for c in range(W - _SIZE + 1):
                b = g[r:r + _SIZE, c:c + _SIZE]
                if (
                    b[2, 2] == 5
                    and bool(np.all(b[0, :] == 9))
                    and bool(np.all(b[1, :] == 9))
                    and bool(np.all(b[3, :] == 9))
                    and bool(np.all(b[4, :] == 9))
                    and b[2, 0] == 9
                    and b[2, 1] == 9
                    and b[2, 3] == 9
                    and b[2, 4] == 9
                ):
                    pos = (r, c)
                    break
            if pos is not None:
                break

    phase1 = False
    if H >= 6 and W >= 8:
        ok = True
        for i in range(3):
            for j in range(3):
                v = g[1 + i, 5 + j]
                if i == 1 and j == 1:
                    if v != 0:
                        ok = False
                        break
                elif v != 9:
                    ok = False
                    break
            if not ok:
                break
        if ok and bool(np.all(g[5, 5:8] == 9)):
            phase1 = True

    if score >= _TOTAL_PROGRESS and pos == _INIT_POS and phase1:
        return g

    if action in (1, 2, 3, 4):
        if pos is not None:
            r, c = pos
            if action == 1:
                nr, nc = r - _STEP, c
            elif action == 2:
                nr, nc = r + _STEP, c
            elif action == 3:
                nr, nc = r, c - _STEP
            else:
                nr, nc = r, c + _STEP

            if nr >= 0 and nc >= 0 and nr + _SIZE < H and nc + _SIZE < W:
                dest = g[nr:nr + _SIZE, nc:nc + _SIZE]
                if bool(np.all(dest == 5)):
                    for i in range(_SIZE):
                        for j in range(_SIZE):
                            if i == 2 and j == 2:
                                continue
                            g[r + i, c + j] = 5
                    for i in range(_SIZE):
                        for j in range(_SIZE):
                            if i == 2 and j == 2:
                                continue
                            g[nr + i, nc + j] = 9

        if score < _TOTAL_PROGRESS and action == _TARGET_SEQ[score]:
            col = W - 1 - score
            if 0 <= col < W:
                g[H - 1, col] = 1

    elif action == 5:
        if H >= 6 and W >= 8 and bool(np.all(g[1:4, 5:8] == 1)):
            for i in range(3):
                for j in range(3):
                    if i == 1 and j == 1:
                        continue
                    g[1 + i, 1 + j] = 2
            g[5, 1:4] = 0

            for i in range(3):
                for j in range(3):
                    if i == 1 and j == 1:
                        continue
                    g[1 + i, 5 + j] = 9
            g[2, 6] = 0
            g[5, 5:8] = 9

    return g


